model Server {
  id                  String           @id @default(cuid())
  name                String
  label               String? // customer-facing nickname (rename)
  // Set when this order arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy, captured by PartnerSourceCapture). Null for every direct
  // Nxeon order. Gates the webhook notify in worker/index.ts on provision success.
  partnerSource       String?
  hostname            String
  vmid                Int?             @unique
  status              ServerStatus     @default(PENDING)
  ipAddress           String?          @unique
  sshPort             Int?             @unique
  rootPassword        String?
  rootPasswordEnc     String?
  isFree              Boolean          @default(false)
  autoRenew           Boolean          @default(true)
  gameVariant         String? // game-server type/loader (e.g. paper, carbon, bepinex) — see lib/game-config
  gameConfig          Json? // per-game settings values (validated against the family schema)
  // Minecraft-only: `<subdomain>.play.nxeon.cloud`, resolved via a per-server DNS
  // SRV record (worker/game-subdomain.ts) instead of the free tier's shared
  // mc-router — see lib/game-subdomain.ts for the shared name-validation rules.
  // Null until the customer sets one; unique across THIS column only — cross-
  // checked against FreeMinecraftServer.subdomain at the application layer since
  // Postgres can't enforce a unique constraint across two different tables.
  subdomain           String?          @unique
  suspendedNote       String?
  // WHY a server is suspended: "UNPAID" | "ABUSE" | "ADMIN". Null = never suspended.
  //
  // `suspendedNote` used to be the only signal, and nothing consumed it, so every
  // suspension looked identical to the billing engine. Two live consequences:
  // (1) `terminateOverdue` selected on `status: "SUSPENDED"` alone, while the
  //     renewal sweep EXCLUDES suspended servers — so an admin suspending a
  //     paid-up customer pending an investigation meant they were never charged,
  //     never warned, their term lapsed, and 13 days later their VM and all its
  //     data were destroyed with a "prolonged non-payment" notice they had never
  //     been given a chance to act on.
  // (2) `renewNow` auto-unsuspended ANY suspended server on payment, so a spammer
  //     suspended for outbound abuse could pay and put themselves straight back
  //     on the network.
  // Both now scope strictly to UNPAID.
  suspendReason       String?
  // Human-readable reason a PROVISION failed terminally, set by the worker on the
  // ERROR path (worker/index.ts). Surfaced on the server detail page's ERROR
  // banner so the customer sees WHAT went wrong instead of a bare red status dot.
  // Cleared when a retry re-enqueues provisioning. Null = never failed (or the
  // failure predates this column).
  provisionError      String?
  // Best-effort, human-readable label for whichever real provisioning phase is
  // running RIGHT NOW (e.g. "Cloning your server…", "Waiting for the game server
  // to start…") — written by worker/index.ts's provision() between real,
  // observable checkpoints (clone / config / start / guest-agent boot / SSH
  // reachable / game port open). Read by lib/provisioning-step.ts and shown by
  // <ProvisioningOverlay/> in place of its cosmetic time-based cycling text.
  // Null = no real signal available yet (falls back to the cosmetic text) or the
  // server isn't mid-provision. Never cleared explicitly — it's simply ignored
  // once status leaves PENDING/PROVISIONING.
  provisioningStep    String?
  expiresAt           DateTime?
  // ---- Dunning (failed auto-charge retry state) ----
  // dunningStage counts CARD ATTEMPTS THAT HAVE FAILED for the current unpaid
  // period: 0 = nothing owed / paid, 1..N = that many failures. Reset to 0 the
  // moment a renewal succeeds. `dunningNextAt` gates the next retry so a
  // 5-minute billing sweep cannot burn every retry in a quarter of an hour, and
  // `dunningPayUrl` is a hosted Checkout link emailed to the customer so they can
  // clear the balance themselves (also how 3-D Secure challenges are satisfied).
  dunningStage        Int              @default(0)
  dunningNextAt       DateTime?
  dunningPayUrl       String?
  // Sent-marker for the pre-renewal "no card on file" reminder (worker/billing.ts
  // renewalReminderSweep). Set to `now` when a card-less owner is reminded that a
  // paid server is about to renew, and reset to null when that period actually
  // renews (commitRenewal), so each cycle can remind at most once. Null = not yet
  // reminded this cycle.
  renewalReminderSentAt DateTime?
  createdAt           DateTime         @default(now())
  updatedAt           DateTime         @updatedAt
  userId              String
  user                User             @relation(fields: [userId], references: [id])
  nodeId              String?
  node                Node?            @relation(fields: [nodeId], references: [id])
  bwInBytes           BigInt           @default(0)
  bwOutBytes          BigInt           @default(0)
  abuseBwMark         BigInt? // last bwOutBytes sample, for outbound-rate abuse detection
  abuseBwMarkAt       DateTime? // when abuseBwMark was taken
  bwWindowStart       DateTime         @default(now())
  termMonths          Int              @default(1) // 1=monthly, 12=annual, 24=biennial, 36=triennial
  /// PERCENT OFF the term-discounted monthly rate that the months currently sitting
  /// between `now` and `expiresAt` were ACTUALLY sold at. This is the rate basis
  /// every proration must price against (lib/proration.ts).
  ///
  /// WHY IT EXISTS (2026-07-26). `prorateDeltaCents` defaulted its rate basis to
  /// `currentPromo(now)` — whatever seasonal promo happened to be running at the
  /// instant a resize was priced. Promos rotate by calendar date from a 15% Launch
  /// Sale to 45% for Cyber Monday, so a customer could upgrade during Cyber Monday
  /// (delta priced at 55% of the honest rate, small charge) and downgrade during
  /// the Launch Sale (delta priced at 85%, large credit) and pocket the 30-point
  /// spread x plan delta x every remaining month — repeatable every promo cycle,
  /// self-service, with the platform's own marketing calendar as the schedule.
  /// lib/promotions.ts is explicit that a promo is a FIRST-TERM intro discount that
  /// renewals never receive, so pricing a mid-term change off today's promo was
  /// wrong even before it was exploitable.
  ///
  /// WHY A PERCENT AND NOT A CENTS RATE. Proration is a DIFFERENCE between two
  /// plans' rates. A stored $/mo figure prices only the plan the server is on and
  /// says nothing about the plan it is moving to, so the other half of the
  /// subtraction would still need a basis invented for it — which is the bug. A
  /// percent is a rate BASIS that applies to any plan price, so both halves of the
  /// delta come from this one persisted number and the round trip is symmetric by
  /// construction rather than by convention. It also survives a plan change with no
  /// write at all: the customer keeps the rate they bought at, so up-then-down is
  /// exactly zero.
  ///
  ///   0   = full price. What BOTH renewal paths bill (worker/billing.ts sweep and
  ///         lib/actions.ts renewNow charge `vpsTermPriceCents` with no promo), and
  ///         what a flat-priced game plan is sold at.
  ///   1-99= a genuine intro/seasonal discount, or a blend of paid and gifted
  ///         months (see prorateBlendPercent in lib/proration.ts).
  ///   100 = gifted. Nothing was paid for these months, so nothing may prorate out
  ///         of them — an admin extension/free grant records this.
  ///   NULL= unknown. Only on rows that predate this column; resolved by an
  ///         EXPLICIT conservative fallback (`resolveTermPromoPercent`), never by
  ///         falling through to today's promo, because that IS the bug above.
  ///
  /// FLOAT, not Int, even though every promo in the catalogue is a whole number.
  /// Blending a renewal into a part-used term lands on halves: 36 months at 45% off
  /// plus 36 renewed at full price is exactly 22.5% off, and rounding that to 23
  /// quietly shaves $7.20 off a $1,071.36 credit. A first term still stores the
  /// promo's exact integer, so the column reads the same for the common case.
  termPromoPercent    Float?
  /// PERCENT the ANNUAL (12-month) commitment discount was set to when THIS server's
  /// term was sold — a snapshot of `annual_discount_percent` (lib/annual-discount.ts)
  /// frozen at the moment of sale, exactly like `termPromoPercent` freezes the seasonal
  /// rate.
  ///
  /// WHY IT EXISTS. The annual discount became an admin-configurable setting, read LIVE
  /// by proration (lib/proration.ts, via `vpsEffectiveMonthly`). Both halves of a resize
  /// round trip therefore priced against whatever the setting held at the instant each
  /// half ran: an admin nudging `annual_discount_percent` between a customer's upgrade
  /// and their downgrade made the credit and the charge disagree, so an annual server's
  /// up-then-down no longer netted to zero. Freezing the rate the server was SOLD at and
  /// reading THAT from both proration directions makes the round trip symmetric by
  /// construction, the same way `termPromoPercent` does for the promo rate.
  ///
  ///   NULL = pre-existing row (predates this column) OR a non-annual/flat-priced server
  ///          that never had an annual discount. Proration falls back to the LIVE setting
  ///          for these — identical maths for every non-annual term, and the best
  ///          available basis for a legacy annual row.
  annualDiscountPct   Float?

  // Parsed from `ua` at ingest time (lib/ua-parse.ts, ua-parser-js) — kept as
  // plain columns rather than re-parsed on every analytics read, same reasoning
  // as country/city below. deviceType is one of "Desktop"/"Mobile"/"Tablet"/
  // "Smart TV"/"Console"/"Wearable"/"XR" (UAParser has no positive "desktop"
  // signal — it's the fallback when no other type is detected). os/browser are
  // UAParser's own display names ("iOS", "Android", "Windows", "macOS", "Linux",
  // "Chrome", "Safari", "Firefox", "Edge", …) — null when ua was missing/unparseable.
  deviceType  String?
  os          String?
  browser     String?
  kind        String   @default("marketing") // marketing | portal
  userId      String?
  country     String?
  region      String?
  city        String?
  lat         Float?
  lng         Float?
  geocoded    Boolean  @default(false)
  // ---- Behaviour + attribution (additive; all nullable / defaulted, safe db push) ----
  // A stable first-party id so RECURRING vs new visitors can be told apart without
  // relying on IP (which NATs many people together and rotates for one person). Set
  // by /api/track from the `nx_vid` cookie, and CONSENT-GATED: null whenever the
  // visitor has opted out ("necessary"), so an opted-out person is only ever counted
  // by the coarse IP path, never given a durable id.
  visitorId   String? // stable per-person id (cookie), null = anon / opted-out
  sessionId   String? // per-tab visit/session id (client-scoped, 30-min idle window)
  pvid        String? // per-pageview id, so a later close-beacon can attach dwell time
  durationMs  Int? // dwell time on THIS pageview, filled in by the close beacon
  isEntry     Boolean  @default(false) // first pageview of its session (the landing page)
  utmSource   String? // ?utm_source — which ad/source sent them
  utmMedium   String? // ?utm_medium — cpc / email / social …
  utmCampaign String? // ?utm_campaign — which campaign
  // Google Ads click id (auto-tagging `?gclid=…`). Captured so paid Google clicks
  // are attributable even though they carry no utm_source; when present /api/track
  // also labels the visit google/cpc. Powers the Google Ads admin diagnostic.
  gclid       String?
  createdAt   DateTime @default(now())

  @@index([createdAt])
  @@index([ip])
  @@index([visitorId])
  @@index([sessionId])
  @@index([pvid])
  @@index([gclid])
}

/// Daily rollup of first-party visitor behaviour, maintained by the worker
/// (worker/analytics.ts, visitorRollupSweep). Keeps the admin audience dashboard's
/// trend series and long-range history cheap as the raw `Visit` log grows past what
/// is comfortable to scan live. Purely additive: nothing reads or writes it except
/// the rollup sweep and the audience page (which overlays a live "today" on top).
model VisitorDaily {
  id                String   @id @default(cuid())
  date              DateTime @unique // UTC midnight of the day this row summarises
  pageviews         Int      @default(0)
  sessions          Int      @default(0)
  uniqueVisitors    Int      @default(0) // distinct visitorId (falling back to ip)
  newVisitors       Int      @default(0) // first ever seen on this day
  returningVisitors Int      @default(0) // seen on some earlier day too
  bounces           Int      @default(0) // single-pageview sessions
  totalSessionMs    BigInt   @default(0) // Σ session dwell — divide by sessions for avg time on site
  signups           Int      @default(0) // accounts created this day
  deployed          Int      @default(0) // of those accounts, how many deployed a server
  updatedAt         DateTime @updatedAt

  @@index([date])
}

// ---- Deploy-wizard funnel + failure tracking ----
// One row per meaningful moment in a deploy wizard, emitted fire-and-forget by
// the customer wizards (components/customer/*DeployWizard.tsx) and by the
// order/provision path when it fails. `type` distinguishes the three things the
// owner needs to tell apart:
//   - "step"     : the user REACHED this step (drives the classic reach/drop-off funnel)
//   - "error"    : something FAILED on this step — a validation error, an API/
//                  provision failure, an exception. `errorCode`/`errorMessage`
//                  say WHAT tripped them up (bug vs abandonment).
//   - "complete" : the deploy SUCCEEDED (bottom of the funnel).
// All ids are nullable so an anonymous / opted-out session still records shape.
// `stepIndex` is the step's position within that session's wizard so events sort
// into wizard order even though optional steps shift the numbering.
model DeployFunnelEvent {
  id           String   @id @default(cuid())
  userId       String? // signed-in account, when resolvable server-side
  visitorId    String? // stable cookie id, when consent allows
  sessionId    String? // per-tab session id (client), the primary dedupe key
  product      String // vps | game | hosting
  step         String // wizard step label reached / that errored
  stepIndex    Int // position of that step within the session's wizard
  type         String   @default("step") // step | error | complete
  errorCode    String? // machine code for an error event (e.g. PROVISION_FAILED)
  errorMessage String? // human error text, truncated
  createdAt    DateTime @default(now())

  @@index([product, createdAt])
  @@index([product, type])
}

// ---- Geo cache (IP -> location), populated best-effort by the worker ----
model GeoCache {
  ip        String   @id
  country   String?
  region    String?
  city      String?
  lat       Float?
  lng       Float?
  createdAt DateTime @default(now())
}

// ---- Teams / organizations ----
model Organization {

1	import { Agent, fetch as undiciFetch } from "undici";
2	import { SANDBOX } from "./sandbox";
3	
4	const insecureAgent = new Agent({ connect: { rejectUnauthorized: false } });
5	
6	const BASE = process.env.PROXMOX_API_URL ?? "https://127.0.0.1:8006";
7	const NODE = process.env.PROXMOX_NODE ?? "";
8	const TOKEN = `PVEAPIToken=${process.env.PROXMOX_TOKEN_ID}=${process.env.PROXMOX_TOKEN_SECRET}`;
9	
10	export class ProxmoxError extends Error {
11	  constructor(message: string, public status: number, public body?: string) {
12	    super(message);
13	  }
14	}
15	
16	async function pveRequestTo(
17	  base: string,
18	  token: string,
19	  method: "GET" | "POST" | "PUT" | "DELETE",
20	  path: string,
21	  params?: Record<string, string | number | undefined>
22	): Promise<any> {
23	  const url = new URL(`${base}/api2/json${path}`);
24	  let body: string | undefined;
25	  const headers: Record<string, string> = { Authorization: token };
26	
27	  const clean = Object.fromEntries(
28	    Object.entries(params ?? {}).filter(([, v]) => v !== undefined)
29	  ) as Record<string, string>;
30	
31	  if (method === "GET" || method === "DELETE") {
32	    for (const [k, v] of Object.entries(clean)) url.searchParams.set(k, String(v));
33	  } else {
34	    body = new URLSearchParams(clean as Record<string, string>).toString();
35	    headers["Content-Type"] = "application/x-www-form-urlencoded";
36	  }
37	
38	  const res = await undiciFetch(url, { method, headers, body, dispatcher: insecureAgent });
39	  const text = await res.text();
40	  if (!res.ok) {
41	    throw new ProxmoxError(`PVE ${method} ${path} -> ${res.status}`, res.status, text);
42	  }
43	  try {
44	    return JSON.parse(text).data;
45	  } catch {
46	    return text;
47	  }
48	}
49	
50	function pveRequest(
51	  method: "GET" | "POST" | "PUT" | "DELETE",
52	  path: string,
53	  params?: Record<string, string | number | undefined>
54	) {
55	  return pveRequestTo(BASE, TOKEN, method, path, params);
56	}
57	
58	export const pve = {
59	  get: (path: string, params?: Record<string, any>) => pveRequest("GET", path, params),
60	  post: (path: string, params?: Record<string, any>) => pveRequest("POST", path, params),
61	  put: (path: string, params?: Record<string, any>) => pveRequest("PUT", path, params),
62	  del: (path: string, params?: Record<string, any>) => pveRequest("DELETE", path, params),
63	};
64	
65	export const node = NODE;
66	
67	/** Connection details for a specific Node row (see Prisma `Node`). */
68	export type NodeConn = {
69	  apiUrl: string;
70	  pveNode: string;
71	  tokenId: string;
72	  tokenSecret: string;
73	};
74	
75	export type PveClient = {
76	  get: (path: string, params?: Record<string, any>) => Promise<any>;
77	  post: (path: string, params?: Record<string, any>) => Promise<any>;
78	  put: (path: string, params?: Record<string, any>) => Promise<any>;
79	  del: (path: string, params?: Record<string, any>) => Promise<any>;
80	  node: string;
81	  waitForTask: (upid: string, timeoutMs?: number) => Promise<void>;
82	  nextVmid: () => Promise<number>;
83	  vmStatus: (vmid: number) => Promise<any>;
84	};
85	
86	/** Build a Proxmox client bound to a specific node. Use in the worker for multi-node. */
87	export function pveFor(conn: NodeConn): PveClient {
88	  const token = `PVEAPIToken=${conn.tokenId}=${conn.tokenSecret}`;
89	  const req = (m: "GET" | "POST" | "PUT" | "DELETE", path: string, params?: Record<string, any>) =>
90	    pveRequestTo(conn.apiUrl, token, m, path, params);
91	  const client: PveClient = {
92	    get: (p, params) => req("GET", p, params),
93	    post: (p, params) => req("POST", p, params),
94	    put: (p, params) => req("PUT", p, params),
95	    del: (p, params) => req("DELETE", p, params),
96	    node: conn.pveNode,
97	    async waitForTask(upid: string, timeoutMs = 300_000) {
98	      const start = Date.now();
99	      while (Date.now() - start < timeoutMs) {
100	        const status = await req("GET", `/nodes/${conn.pveNode}/tasks/${encodeURIComponent(upid)}/status`);
101	        if (status.status === "stopped") {
102	          if (status.exitstatus !== "OK") throw new Error(`Proxmox task failed: ${status.exitstatus}`);
103	          return;
104	        }
105	        await new Promise((r) => setTimeout(r, 2000));
106	      }
107	      throw new Error(`Proxmox task timed out: ${upid}`);
108	    },
109	    async nextVmid() {
110	      return Number(await req("GET", "/cluster/nextid"));
111	    },
112	    async vmStatus(vmid: number) {
113	      return req("GET", `/nodes/${conn.pveNode}/qemu/${vmid}/status/current`);
114	    },
115	  };
116	  return client;
117	}
118	
119	export async function waitForTask(upid: string, timeoutMs = 300_000): Promise<void> {
120	  const start = Date.now();
121	  while (Date.now() - start < timeoutMs) {
122	    const status = await pve.get(`/nodes/${NODE}/tasks/${encodeURIComponent(upid)}/status`);
123	    if (status.status === "stopped") {
124	      if (status.exitstatus !== "OK") {
125	        throw new Error(`Proxmox task failed: ${status.exitstatus}`);
126	      }
127	      return;
128	    }
129	    await new Promise((r) => setTimeout(r, 2000));
130	  }
131	  throw new Error(`Proxmox task timed out: ${upid}`);
132	}
133	
134	// ---------------------------------------------------------------------------
135	// Live task progress (vzdump backup / qmrestore restore)
136	// ---------------------------------------------------------------------------
137	
138	/** Minimal shape any progress poller needs — satisfied by `pve` and `pveFor`. */
139	export type TaskClient = {
140	  get: (path: string, params?: Record<string, any>) => Promise<any>;
141	  node: string;
142	};
143	
144	export type TaskPhase = "backup" | "restore";
145	
146	/**
147	 * Parse the latest completion percentage and a human step out of Proxmox task
148	 * log lines. vzdump/qmrestore emit lines such as:
149	 *   "INFO:  42% (4.6 GiB of 11.0 GiB) in 12s, read: ..."
150	 *   "INFO: status: 42%"
151	 *   "progress 42% (read 4.6 GiB, ...)"
152	 *   "INFO: creating vzdump archive '/mnt/backup/...'"
153	 * Returns the last percentage seen (or null) plus a coarse step label.
154	 */
155	export function parseTaskProgress(
156	  lines: string[],
157	  phase: TaskPhase
158	): { pct: number | null; step: string | null } {
159	  let pct: number | null = null;
160	  let step: string | null = null;
161	  const verb = phase === "restore" ? "Restoring archive" : "Creating archive";
162	
163	  for (const raw of lines) {
164	    const line = String(raw ?? "");
165	    const m = line.match(/(\d{1,3})\s*%/);
166	    if (m) {
167	      const v = Number(m[1]);
168	      if (v >= 0 && v <= 100) pct = v;
169	    }
170	    const l = line.toLowerCase();
171	    if (l.includes("creating vzdump archive") || l.includes("starting new backup")) step = "Creating archive";
172	    else if (l.includes("restore") && (l.includes("start") || l.includes("archive"))) step = "Restoring archive";
173	    else if (l.includes("uploading") || l.includes("upload")) step = "Uploading backup";
174	    else if (l.includes("transferred") || l.includes("read:")) step = verb;
175	    else if (l.includes("finished") || l.includes("finalize") || l.includes("closing")) step = "Finalizing";
176	  }
177	  if (pct !== null && step) step = `${step}… ${pct}%`;
178	  return { pct, step: step ?? (pct !== null ? `${verb}… ${pct}%` : null) };
179	}
180	
181	/**
182	 * Wait for a Proxmox task while streaming live progress. Polls `/status` (to
183	 * detect completion) and `/tasks/<upid>/log` (for the percentage) every ~2s and
184	 * invokes `onProgress(progress, step)` on each tick.
185	 *
186	 * Progress is monotonic and never regresses. The parsed task percentage (0..100)
187	 * is mapped into the caller's [base, base+span] window so multi-phase callers
188	 * (e.g. restore = stop→restore→start) can reserve sub-ranges. When no % has been
189	 * parsed yet, a coarse time-based creep keeps the bar moving up to a cap.
190	 */
191	export async function waitForTaskProgress(
192	  client: TaskClient,
193	  upid: string,
194	  onProgress: (progress: number, step: string) => void | Promise<void>,
195	  opts: { timeoutMs?: number; phase?: TaskPhase; base?: number; span?: number } = {}
196	): Promise<void> {
197	  const timeoutMs = opts.timeoutMs ?? 3_600_000;
198	  const phase = opts.phase ?? "backup";
199	  const base = opts.base ?? 0;
200	  const span = opts.span ?? 100;
201	  const enc = encodeURIComponent(upid);
202	
203	  const start = Date.now();
204	  let reported = base; // last value handed to onProgress (monotonic)
205	  let creep = 0; // coarse fallback estimate while no % is available
206	
207	  while (Date.now() - start < timeoutMs) {
208	    let stopped = false;
209	    let exitOk = true;
210	
211	    try {
212	      const status = await client.get(`/nodes/${client.node}/tasks/${enc}/status`);
213	      if (status?.status === "stopped") {
214	        stopped = true;
215	        exitOk = status.exitstatus === "OK";
216	      }
217	    } catch {
218	      /* transient — try again next tick */
219	    }
220	
221	    // Read the log tail and parse the newest percentage/step. Cheap enough for a
222	    // single VM backup; failures are non-fatal.
223	    let step: string | null = null;
224	    let pct: number | null = null;
225	    try {
226	      const log = await client.get(`/nodes/${client.node}/tasks/${enc}/log`, { start: 0, limit: 400 });
227	      const lines: string[] = Array.isArray(log) ? log.map((e: any) => e?.t ?? "") : [];
228	      const parsed = parseTaskProgress(lines, phase);
229	      pct = parsed.pct;
230	      step = parsed.step;
231	    } catch {
232	      /* ignore */
233	    }
234	
235	    // Compute the target within [base, base+span].
236	    let target: number;
237	    if (pct !== null) {
238	      target = base + (span * pct) / 100;
239	    } else {
240	      // Coarse creep: advance slowly toward 85% of the window until a % appears.
241	      creep = Math.min(creep + 4, 85);
242	      target = base + (span * creep) / 100;
243	    }
244	    if (target > reported) reported = target;
245	
246	    if (!stopped) {
247	      await onProgress(Math.round(Math.min(reported, base + span)), step ?? (phase === "restore" ? "Restoring…" : "Creating archive…"));
248	    }
249	
250	    if (stopped) {
251	      if (!exitOk) {
252	        // Surface the real failure reason from the log tail when available.
253	        throw new Error(`Proxmox task failed: ${upid}`);
254	      }
255	      return;
256	    }
257	
258	    await new Promise((r) => setTimeout(r, 2000));
259	  }
260	  throw new Error(`Proxmox task timed out: ${upid}`);
261	}
