635	/**
636	 * Force the CURRENT (DB) root password onto a running guest via the QEMU guest
637	 * agent — no reboot, no dependence on cloud-init. Same primitive `passwordReset`
638	 * (worker/index.ts) uses to change a password live; pulled out here so any other
639	 * caller whose action replaces or reverts the VM's actual disk content can reuse
640	 * it, rather than re-deriving the QGA call.
641	 *
642	 * WHY THIS EXISTS BEYOND passwordReset: `SNAPSHOT_ROLLBACK` and `BACKUP_RESTORE`
643	 * both put an OLDER copy of the guest's real disk back — including whatever
644	 * `/etc/shadow` existed at snapshot/backup time — while `Server.rootPasswordEnc`
645	 * in the DB keeps whatever the CURRENT password is. If a `PASSWORD_RESET` (or
646	 * any other password change) happened between that snapshot/backup being taken
647	 * and it being rolled back to / restored from, the guest reverts to the OLDER
648	 * password while the DB still holds the NEWER one — every later SSH from the
649	 * platform (control panel, GAME_POWER, mods, backups) then authenticates with
650	 * the DB's password against a guest that has a different one, failing with "All
651	 * configured authentication methods failed". This is the identical divergence
652	 * class documented on `provision()`'s password-reuse fix, just reached by
653	 * reverting old disk state instead of a retried clone — see that comment for the
654	 * full incident. Callers must invoke this after the VM is confirmed running and
655	 * its guest agent has answered (e.g. via `waitForGuestAgent`).
656	 *
657	 * Best-effort: never throws. Returns whether the QGA call was accepted — false
658	 * means the guest's password could not be confirmed resynced, which callers
659	 * should log loudly rather than silently swallow (the rollback/restore itself
660	 * still genuinely succeeded, so this must not fail that job).
661	 */
662	export async function applyPasswordToGuest(conn: PveClient, vmid: number, password: string): Promise<boolean> {
663	  try {
664	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/agent/set-user-password`, {
665	      username: "root",
666	      password,
667	    });
668	    if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
669	    return true;
670	  } catch (e) {
671	    console.error(`[proxmox] applyPasswordToGuest failed for vmid ${vmid}`, e);
672	    return false;
673	  }
674	}
