706	// ---------------------------------------------------------------------------
707	// Platform backups vs customer backups
708	// ---------------------------------------------------------------------------
709	//
710	// DATA LOSS PREVENTED (real, on this host, 2026-07-26): `scripts/backup-vms.sh`
711	// used to write the platform's own host-level disaster-recovery archives into the
712	// SAME Proxmox storage (`backup` -> /tank/backup/dump) that customers' on-demand
713	// backups land in, and `pruneBackups` below selected victims with nothing but
714	// `b.vmid === vmid`. So vmid 102 ended the 04:31 platform run holding two
715	// archives — the customer's own manual one from 2026-07-25 12:22 and the
716	// platform's 10 GB DR copy from 2026-07-26 04:31 — and the customer's very next
717	// click on "Create backup" (keep = CUSTOMER_BACKUP_KEEP = 2) would have deleted
718	// the platform's copy of their VM. Repeated across the fleet that silently
719	// destroys the entire bare-metal recovery set, one customer click at a time.
720	//
721	// The fix is three independent layers, in order of strength:
722	//
723	//  1. STRUCTURAL. `scripts/backup-vms.sh` now writes with `vzdump --dumpdir
724	//     /tank/backup/platform`, a directory that is NOT the `dump/` subdirectory of
725	//     any configured PVE storage. Proxmox only indexes `<storage-path>/dump`, so
726	//     platform archives have no `volid` at all: they cannot appear in the
727	//     `/storage/backup/content` listing this function iterates, and there is no
728	//     volid string that `DELETE /storage/backup/content/<volid>` could resolve to
729	//     them. Not "filtered out" — not addressable.
730	//  2. CHOKEPOINT. `deleteBackup` is the only function in the repo that issues a
731	//     storage-content DELETE (whole-repo grep: this file plus its single caller in
732	//     worker/index.ts). It re-derives protection for every volid immediately
733	//     before deleting and refuses on any of: the PVE `protected` attribute, the
734	//     platform notes marker, or the protection registry — and it fails CLOSED if
735	//     it cannot determine the answer.
736	//  3. MARKER + REGISTRY. If the platform job is ever pointed back at a shared PVE
737	//     storage (`NXEON_VM_BACKUP_STORAGE=backup`), it stamps each archive with
738	//     `--notes-template` carrying PLATFORM_BACKUP_MARKER and appends the volid to
739	//     PROTECTED_REGISTRY. Both are honoured below, which also covers the archives
740	//     already sitting in /tank/backup/dump from the 2026-07-26 04:31 run, written
741	//     before layer 1 existed.
742	
743	/** Where the platform's own whole-system vzdump archives live — outside every PVE storage. */
744	export const PLATFORM_BACKUP_DIR = process.env.NXEON_PLATFORM_BACKUP_DIR ?? "/tank/backup/platform";
745	
746	/**
747	 * Stamped into the vzdump notes of platform archives (see `--notes-template` in
748	 * scripts/backup-vms.sh). Customer retention must never delete an archive whose
749	 * notes contain this string.
750	 */
751	export const PLATFORM_BACKUP_MARKER = "NXEON-PLATFORM-BACKUP";
752	
753	/**
754	 * One volid per line. Maintained by scripts/backup-vms.sh; also seeded with any
755	 * pre-existing platform archives that were written into the shared storage before
756	 * the dumpdir split. Anything listed here is undeletable through this module.
757	 */
758	const PROTECTED_REGISTRY = `${PLATFORM_BACKUP_DIR}/PROTECTED-VOLIDS`;
759	
760	/**
761	 * Read the protection registry.
762	 *
763	 * Returns `null` when the registry exists but could not be read. Callers MUST
764	 * treat `null` as "protection state unknown" and refuse to delete: a transient
765	 * EIO on this file must not be the thing that lets a customer's prune wipe the
766	 * platform's recovery set. A registry that simply does not exist yet (fresh
767	 * install, platform job has never run) is a legitimate empty set — layer 1 means
768	 * there is nothing in the shared storage to protect in that case anyway.
769	 */
770	async function protectedVolids(): Promise<Set<string> | null> {
771	  const { readFile } = await import("node:fs/promises");
772	  try {
773	    const raw = await readFile(PROTECTED_REGISTRY, "utf8");
774	    return new Set(
775	      raw.split("\n").map((l) => l.trim()).filter((l) => l.length > 0 && !l.startsWith("#"))
776	    );
777	  } catch (e: any) {
778	    if (e?.code === "ENOENT") return new Set();
779	    console.error(`[proxmox] protection registry ${PROTECTED_REGISTRY} unreadable — refusing to prune`, e);
780	    return null;
781	  }
782	}
783	
784	/** Shape of one entry in `/nodes/<node>/storage/<sid>/content`. */
785	/**
786	 * Every backup archive the `backup` storage holds for one VMID, read through a
787	 * node-scoped client. This is the READ-BACK that `backupCreate` uses to prove an
788	 * archive actually exists: the vzdump task's exit status says the task ran, not
789	 * that a file landed. See worker/backup-schedule.ts (`freshBackupProof`) and
790	 * incident H4.
791	 */
792	export async function listBackupsOn(client: any, vmid: number): Promise<StorageBackupEntry[]> {
793	  const content: StorageBackupEntry[] = await client.get(
794	    `/nodes/${client.node}/storage/backup/content`,
795	    { content: "backup" }
796	  );
797	  return content.filter((b) => b.vmid === vmid && typeof b.volid === "string");
798	}
799	
800	export type StorageBackupEntry = {
801	  volid?: string;
802	  vmid?: number;
803	  ctime?: number;
804	  size?: number;
805	  notes?: string;
806	  protected?: boolean | number;
807	};
808	
809	/**
810	 * Is this archive one of the platform's own (i.e. never customer-prunable)?
811	 * Any single signal is enough — they are deliberately redundant.
812	 */
813	export function isPlatformArchive(b: StorageBackupEntry, registry: Set<string>): boolean {
814	  if (b.protected) return true;
815	  if (typeof b.notes === "string" && b.notes.includes(PLATFORM_BACKUP_MARKER)) return true;
816	  if (typeof b.volid === "string" && registry.has(b.volid)) return true;
817	  return false;
818	}
819	
820	/**
821	 * Delete one backup archive by its Proxmox volume id. `client` = the node's pve client.
822	 *
823	 * This is the ONLY storage-content DELETE in the codebase, so it is where the
824	 * "a customer can never delete a platform archive" invariant is enforced rather
825	 * than merely intended. It re-checks protection against the live hypervisor for
826	 * the exact volid being deleted — a caller that passed a stale or hand-crafted
827	 * volid cannot slip past it. Every uncertain outcome throws.
828	 */
829	export async function deleteBackup(client: any, volid: string): Promise<void> {
830	  // Only `<storage>:backup/<basename>` volids are deletable here. Rejecting
831	  // anything else keeps a malformed or path-traversing volid from ever reaching
832	  // the API, and keeps this function honest about what it operates on.
833	  const m = /^([A-Za-z0-9._-]+):backup\/([^/]+)$/.exec(volid);
834	  if (!m) throw new Error(`refusing to delete: '${volid}' is not a <storage>:backup/<file> volid`);
835	
836	  const registry = await protectedVolids();
837	  if (registry === null) {
838	    throw new Error(`refusing to delete ${volid}: platform protection registry unreadable`);
839	  }
840	  if (registry.has(volid)) {
841	    throw new Error(`refusing to delete ${volid}: listed in the platform protection registry`);
842	  }
843	
844	  // Ask the hypervisor about this exact volume. `notes` and `protected` are both
845	  // returned by the content-info endpoint (PVE::API2::Storage::Content). A failure
846	  // here means we do not know whether this is a platform archive, so we stop.
847	  let info: any;
848	  try {
849	    info = await client.get(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
850	  } catch (e) {
851	    throw new Error(`refusing to delete ${volid}: could not read its attributes (${e})`);
852	  }
853	  if (isPlatformArchive({ volid, notes: info?.notes, protected: info?.protected }, registry)) {
854	    throw new Error(`refusing to delete ${volid}: it is a platform (host-level) backup`);
855	  }
856	
857	  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
858	}
859	
860	/**
861	 * Retention for ONE CUSTOMER SERVER: keep only the newest `keep` archives that
862	 * belong to that customer, deleting the older ones (best-effort per file, oldest
863	 * first). Runs after every successful customer backup, and from the standalone
864	 * sweep in worker/backup-schedule.ts. Returns how many were deleted.
865	 *
866	 * Platform archives are excluded from the delete set AND from the retention
867	 * count. Counting them would be its own bug: with keep = 2, three platform
868	 * archives of a vmid would make every customer archive "older than the newest
869	 * two" and delete all of the customer's backups instead.
870	 */
871	export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
872	  // `keep` decides how many of a customer's restore points survive, so it is
873	  // validated rather than trusted. `mine.slice(Math.max(0, keep))` looks safe and
874	  // is not: Math.max(0, NaN) is NaN, Array.slice(NaN) coerces to slice(0), and the
875	  // delete set silently becomes EVERY backup the customer has. A keep that arrived
876	  // as undefined, "" or a bad Settings parse would wipe the lot with no error on
877	  // the way past. Fail closed instead — an over-retained archive costs disk, a
878	  // missing one costs the customer their only restore point.
879	  if (!Number.isInteger(keep) || keep < 1) {
880	    throw new Error(
881	      `pruneBackups: refusing to prune vmid ${vmid} with keep='${keep}' — ` +
882	        `retention must be a whole number of at least 1.`
883	    );
884	  }
885	
886	  const registry = await protectedVolids();
887	  if (registry === null) {
888	    // Fail closed: no retention this pass. Archives accumulating for one cycle is
889	    // recoverable; deleting the platform's only copy of a VM is not.
890	    console.error(`[proxmox] pruneBackups: protection state unknown, skipping prune for vmid ${vmid}`);
891	    return 0;
892	  }
893	
894	  const forVmid = await listBackupsOn(client, vmid);
895	  const shielded = forVmid.filter((b) => isPlatformArchive(b, registry));
896	  const mine = forVmid
897	    .filter((b) => !isPlatformArchive(b, registry))
898	    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
899	
900	  if (shielded.length > 0) {
901	    console.log(
902	      `[proxmox] pruneBackups: vmid ${vmid} — ${shielded.length} platform archive(s) excluded from retention`
903	    );
904	  }
905	
906	  const toDelete = mine.slice(Math.max(0, keep));
907	  let deleted = 0;
908	  for (const b of toDelete) {
909	    try {
910	      await deleteBackup(client, b.volid!);
911	      deleted++;
912	    } catch (e) {
913	      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
914	    }
915	  }
916	  return deleted;
917	}
918	
919	export async function storageStatus(storage: string): Promise<any> {
920	  return pve.get(`/nodes/${NODE}/storage/${storage}/status`);
921	}
