1	// Per-node capacity / utilization math for the node-capacity warning feature.
2	//
3	// Plain (non-"use server") module — safe to import from admin server components
4	// (the Compute-nodes and Web-hosting pages render bars off it) AND from the
5	// worker sweep (worker/monitor.ts → nodeCapacitySweep raises/clears NodeAlerts
6	// off it). No mutations here; the alert lifecycle lives in the worker so this
7	// file stays a pure-ish reader other surfaces can share, exactly like the
8	// read-only helpers in lib/monitoring.ts.
9	//
10	// TWO NODE TYPES, ONE MODEL. Nxeon schedules customer VMs onto Proxmox `Node`s
11	// and shared-hosting accounts onto `HostingNode`s. Both fill up and both refuse
12	// new work when they do, so both are reduced to the same shape: a list of
13	// per-DIMENSION utilization percentages (CPU/RAM/DISK for Proxmox, ACCOUNTS/DISK
14	// for hosting) that the thresholds below turn into OK / WARN / CRITICAL.
15	//
16	// ALLOCATION vs REAL USAGE. For each dimension we take the WORSE of two numbers:
17	//   - allocation: what the DB has COMMITTED to the node (sum of every server's
18	//     plan RAM/disk/vCPU, or the account count). This is what makes the NEXT
19	//     provision fail — a node can be 100% committed while barely warm.
20	//   - real usage: what Proxmox actually reports in use right now (RAM/CPU/disk),
21	//     which is what makes a node DEGRADE.
22	// Warning on max(alloc, real) means we fire on whichever ceiling is hit first,
23	// which is the honest "add a node before this bites" signal the feature exists
24	// to give.
25	
26	import { db } from "./db";
27	import { nodeRamUsage, nodeStorageUsage, type NodeRam, type StorageUsage } from "./monitoring";
28	import { effectiveDiskGB } from "./extra-disk";
29	import { getSettingInt } from "./settings";
30	// severityFor/capBarColor/CapSeverity/NodeThresholds live in capacity-severity.ts
31	// (a dependency-free, client-safe module) and are re-exported here unchanged —
32	// see that file's doc comment for why they were split out.
33	import { severityFor, capBarColor, type CapSeverity, type NodeThresholds } from "./capacity-severity";
34	
35	export { severityFor, capBarColor, type CapSeverity, type NodeThresholds };
36	
37	const MB = 1024 * 1024;
38	const GB = 1024 ** 3;
39	
40	export type CapDimension = "CPU" | "RAM" | "DISK" | "ACCOUNTS";
41	export type NodeKind = "PROXMOX" | "HOSTING";
42	
43	export const NODE_CAP_DEFAULT_WARN = 80;
44	export const NODE_CAP_DEFAULT_CRIT = 90;
45	
46	/**
47	 * Hysteresis: an OPEN alert only auto-resolves once utilization falls this many
48	 * points BELOW the WARN threshold. Without the gap a node parked right on the
49	 * line (79 ⇄ 81) would flap open/closed every sweep and bury the operator in
50	 * churn. Env-overridable for tuning without a redeploy.
51	 */
52	export const NODE_CAP_RESOLVE_MARGIN = Number(process.env.NXEON_NODE_ALERT_RESOLVE_MARGIN ?? 5);
53	
54	/**
55	 * A persistent (unchanged-severity) condition re-notifies at most once per this
56	 * many hours — the debounce that stops "node stuck at 92%" emailing ops every
57	 * 10-minute sweep. A NEW alert and a WARN⇄CRITICAL change always notify
58	 * immediately regardless of the cooldown.
59	 */
60	export const NODE_CAP_COOLDOWN_HOURS = Number(process.env.NXEON_NODE_ALERT_COOLDOWN_HOURS ?? 6);
61	
62	/**
63	 * Every server status EXCEPT DELETING still holds committed capacity on its node
64	 * — its VM (and its RAM/disk reservation) exists until the delete completes. This
65	 * matches the exclusion the existing scheduler and infra pages already use
66	 * (`status: { not: "DELETING" }`), so the utilization shown here agrees with what
67	 * scheduleNode commits against.
68	 */
69	const VPS_COMMITTED_EXCLUDE = ["DELETING"] as const;
70	/** Hosting-account statuses that still occupy a slot / quota on their node. */
71	const HOSTING_LIVE_STATUSES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;
72	
73	/**
74	 * Resolve the admin-configured thresholds, clamped so they are always usable:
75	 * both in 1..100, and CRITICAL never below WARN (a CRITICAL under WARN would make
76	 * the amber band unreachable and every warn instantly read critical).
77	 */
78	export async function nodeThresholds(): Promise<NodeThresholds> {
79	  let warnPct = await getSettingInt("node_warn_pct", NODE_CAP_DEFAULT_WARN);
80	  let critPct = await getSettingInt("node_critical_pct", NODE_CAP_DEFAULT_CRIT);
81	  if (!Number.isFinite(warnPct) || warnPct < 1 || warnPct > 100) warnPct = NODE_CAP_DEFAULT_WARN;
82	  if (!Number.isFinite(critPct) || critPct < 1 || critPct > 100) critPct = NODE_CAP_DEFAULT_CRIT;
83	  if (critPct < warnPct) critPct = warnPct;
84	  return { warnPct, critPct };
85	}
86	
87	
88	/** The percent below which an OPEN alert is allowed to auto-resolve. */
89	export function resolveFloor(t: NodeThresholds): number {
90	  return Math.max(0, t.warnPct - NODE_CAP_RESOLVE_MARGIN);
91	}
92	
93	export type DimUtil = {
94	  dimension: CapDimension;
95	  /** The value thresholded — the worse of allocation and real usage. */
96	  pct: number;
97	  /** DB-committed percent (null when the dimension has no allocation basis). */
98	  allocPct: number | null;
99	  /** Live-usage percent from Proxmox (null when unreachable / not applicable). */
100	  realPct: number | null;
101	  /** Short human breakdown, e.g. "48 / 56 GB committed · 61% used". */
102	  detail: string;
103	};
104	
105	export type NodeUtil = {
106	  kind: NodeKind;
107	  id: string;
108	  name: string;
109	  enabled: boolean;
110	  /** For Proxmox: node status endpoint reachable. Hosting is DB-only → always true. */
111	  reachable: boolean;
112	  dims: DimUtil[];
113	  /** Worst dimension percent across `dims` (0 when there are none). */
114	  worstPct: number;
115	  severity: CapSeverity;
116	};
117	
118	function pct(part: number, whole: number): number | null {
119	  if (!(whole > 0)) return null;
120	  return (part / whole) * 100;
121	}
122	
123	/** Combine allocation + real into the thresholded value (worse of the two). */
124	function worse(allocPct: number | null, realPct: number | null): number {
125	  return Math.max(allocPct ?? 0, realPct ?? 0);
126	}
127	
128	function rollup(dims: DimUtil[], t: NodeThresholds): { worstPct: number; severity: CapSeverity } {
129	  const worstPct = dims.reduce((m, d) => Math.max(m, d.pct), 0);
130	  return { worstPct, severity: severityFor(worstPct, t) };
131	}
132	
133	// ---------------------------------------------------------------------------
134	// Proxmox compute nodes
135	// ---------------------------------------------------------------------------
136	
137	/**
138	 * Utilization for every registered Proxmox node.
139	 *
140	 * RAM is always computable (allocation from `Node.capacityRamMB` + the sum of
141	 * each live server's `plan.ramMB`; real usage from the node status endpoint when
142	 * reachable). CPU and DISK need Proxmox to be reachable for their denominator
143	 * (physical thread count / storage pool size), so on an unreachable node they are
144	 * simply omitted rather than guessed — `reachable:false` tells the UI and the
145	 * sweep to treat their absence as "unknown", never as "recovered".
146	 */
147	export async function proxmoxNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
148	  const nodes = await db.node.findMany({
149	    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
150	    include: {
151	      servers: {
152	        where: { status: { notIn: [...VPS_COMMITTED_EXCLUDE] } },
153	        select: {
154	          extraDiskGB: true,
155	          plan: { select: { cpuCores: true, ramMB: true, diskGB: true } },
156	        },
157	      },
158	    },
159	  });
160	
161	  // Real usage, best-effort. Keyed by node NAME — nodeRamUsage/nodeStorageUsage
162	  // label every row with `Node.name` (see lib/monitoring.ts nodeTargets).
163	  let ramRows: NodeRam[] = [];
164	  let storageRows: StorageUsage[] = [];
165	  try {
166	    ramRows = await nodeRamUsage();
167	  } catch {
168	    /* leave empty — every node reads unreachable */
169	  }
170	  try {
171	    storageRows = await nodeStorageUsage();
172	  } catch {
173	    /* leave empty */
174	  }
175	  const ramByNode = new Map(ramRows.map((r) => [r.node, r]));
176	
177	  return nodes.map((n) => {
178	    const committedRamMB = n.servers.reduce((s, sv) => s + sv.plan.ramMB, 0);
179	    const committedDiskGB = n.servers.reduce(
180	      (s, sv) => s + effectiveDiskGB(sv.plan.diskGB, sv.extraDiskGB),
181	      0,
182	    );
183	    const committedVcpu = n.servers.reduce((s, sv) => s + sv.plan.cpuCores, 0);
184	
185	    const real = ramByNode.get(n.name);
186	    const reachable = !!real?.reachable;
187	    // The node's own VM-disk pool (storageNvme) is the disk denominator.
188	    const vmStorage = storageRows.find((s) => s.node === n.name && s.storage === n.storageNvme);
189	
190	    const dims: DimUtil[] = [];
191	
192	    // RAM — allocation always available; real when reachable.
193	    {
194	      const allocPct = pct(committedRamMB, n.capacityRamMB);
195	      const realPct = reachable && real ? real.ratio * 100 : null;
196	      const p = worse(allocPct, realPct);
197	      const parts = [
198	        `${(committedRamMB / 1024).toFixed(0)} / ${(n.capacityRamMB / 1024).toFixed(0)} GB committed`,
199	      ];
200	      if (realPct !== null) parts.push(`${Math.round(realPct)}% used`);
201	      dims.push({ dimension: "RAM", pct: p, allocPct, realPct, detail: parts.join(" · ") });
202	    }
203	
204	    // CPU — real usage is the signal (vCPU is normally overcommitted, so an
205	    // allocation ratio is context, not an alarm). Only present when reachable.
206	    if (reachable && real) {
207	      const realPct = real.cpu * 100;
208	      const allocPct = real.cores > 0 ? (committedVcpu / real.cores) * 100 : null;
209	      const parts = [`${Math.round(realPct)}% used`];
210	      if (allocPct !== null) {
211	        parts.push(`${committedVcpu} vCPU / ${real.cores} threads (${Math.round(allocPct)}% committed)`);
212	      }
213	      // CPU is thresholded on REAL load only; overcommit alloc is informational.
214	      dims.push({ dimension: "CPU", pct: realPct, allocPct, realPct, detail: parts.join(" · ") });
215	    }
216	
217	    // DISK — needs the pool size from Proxmox. Allocation = committed effective
218	    // disk vs pool total; real = pool used vs pool total. Worse of the two.
219	    if (vmStorage?.reachable && vmStorage.total > 0) {
220	      const allocPct = pct(committedDiskGB * GB, vmStorage.total);
221	      const realPct = vmStorage.ratio * 100;
222	      const p = worse(allocPct, realPct);
223	      const parts = [
224	        `${committedDiskGB} GB committed of ${(vmStorage.total / GB).toFixed(0)} GB`,
225	        `${Math.round(realPct)}% used`,
226	      ];
227	      dims.push({ dimension: "DISK", pct: p, allocPct, realPct, detail: parts.join(" · ") });
228	    }
229	
230	    return {
231	      kind: "PROXMOX" as const,
232	      id: n.id,
233	      name: n.name,
234	      enabled: n.enabled,
235	      reachable,
236	      dims,
237	      ...rollup(dims, t),
238	    };
239	  });
240	}
