311	/** Every node (both kinds) with its utilization, plus the resolved thresholds. */
312	export async function allNodeUtil(): Promise<{ thresholds: NodeThresholds; nodes: NodeUtil[] }> {
313	  const thresholds = await nodeThresholds();
314	  const [proxmox, hosting] = await Promise.all([
315	    proxmoxNodeUtil(thresholds),
316	    hostingNodeUtil(thresholds),
317	  ]);
318	  return { thresholds, nodes: [...proxmox, ...hosting] };
319	}
320	
321	/**
322	 * Pick the best Proxmox node for a new server of `planRamMB`, when the
323	 * customer didn't choose a location explicitly. Bin-packs onto whichever
324	 * ONLINE, enabled node has the most free RAM after projecting this VM onto
325	 * it, staying under the CRITICAL threshold when any node can (falling back to
326	 * least-bad if every node is already critical).
327	 *
328	 * THIRD copy, consolidated here. This existed as two near-identical private
329	 * copies — `lib/order.ts` (VPS orders) and `lib/actions-nxcloud.ts` (NxCloud
330	 * orders) — and `lib/game-order.ts`'s game-server order path never called
331	 * either one at all: it creates its `Server` row with no `nodeId`, so every
332	 * game server ever ordered falls through `worker/index.ts`'s `nodeFor()`
333	 * fallback (`server.node ?? primary node`) and lands on the PRIMARY node
334	 * regardless of its actual load. Confirmed live: `primary` sits at 84% real
335	 * RAM and 200% committed CPU while other nodes are comparatively idle, and
336	 * every game server in production has `nodeId: null`. Fixed by giving
337	 * `game-order.ts` the same real scheduler VPS/NxCloud orders already use,
338	 * rather than writing a fourth copy or leaving it unscheduled.
339	 */
340	export async function scheduleNode(planRamMB: number) {
341	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
342	  if (nodes.length === 0) return null;
343	  const loads = await Promise.all(
344	    nodes.map(async (n) => {
345	      const agg = await db.server.findMany({
346	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
347	        select: { plan: { select: { ramMB: true } } },
348	      });
349	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
350	      // Commitment AFTER this VM lands — that's what decides whether placing
351	      // here tips the node critical.
352	      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
353	      return { node: n, free: n.capacityRamMB - used, projectedPct };
354	    }),
355	  );
356	  const { critPct } = await nodeThresholds();
357	  const roomy = loads.filter((l) => l.projectedPct < critPct);
358	  const pool = roomy.length > 0 ? roomy : loads;
359	  pool.sort((a, b) => b.free - a.free);
360	  return pool[0].node;
361	}
