13	export function ovhConfigured(): boolean {
14	  return !!(
15	    process.env.OVH_APPLICATION_KEY &&
16	    process.env.OVH_APPLICATION_SECRET &&
17	    process.env.OVH_CONSUMER_KEY
18	  );
19	}
20	
21	function base(): string {
22	  return ENDPOINTS[process.env.OVH_ENDPOINT ?? "ovh-ca"] ?? ENDPOINTS["ovh-ca"];
23	}
