226	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
227	    } catch {
228	      /* best-effort */
229	    }
230	  }
231	  await db.dedicatedIp.update({
232	    where: { id: ip.id },
233	    data: { status: "FREE", serverId: null, virtualMac: null },
234	  });
235	  // `Server.ipAddress` is UNIQUE and separate from this pool table — every
236	  // caller used to have to remember to clear it themselves, and one (the
237	  // admin "release IP" action) didn't, which left a FREE pool row while a
238	  // live server still held that exact address in `Server.ipAddress`. The next
239	  // server to claim the pool row then failed provisioning with a P2002 on
240	  // every retry, deterministically, since the failed-provision cleanup just
241	  // re-freed the same already-stuck row. Clearing it here — for every caller,
242	  // guarded to only touch the row that still holds THIS address, since the
243	  // column also holds ordinary NAT IPs for other servers — closes that class
244	  // of bug for good instead of relying on each call site to remember.
245	  await db.server.updateMany({
246	    where: { id: serverId, ipAddress: ip.address },
247	    data: { ipAddress: null, ipv6: null },
248	  });
249	}
